/* CRC-CCITT unit tests.
 *
 * Vectors: the canonical CRC-16/CCITT-FALSE check value ("123456789" ->
 * 0x29B1) and the golden sectors generated by tests/gen_golden.py, whose
 * CRCs were computed with binascii.crc_hqx — an implementation fully
 * independent of the C code under test. */
#include "onboard.h"
#include "golden.h"
#include <string.h>

static int fails = 0;

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
            fails++;                                                    \
        }                                                               \
    } while (0)

int main(void)
{
    /* canonical check value for poly 0x1021 / init 0xFFFF / msb-first */
    CHECK(rslap_crc_ccitt((const uint8_t *)"123456789", 9) == 0x29B1);
    CHECK(rslap_crc_ccitt((const uint8_t *)"", 0) == 0xFFFF);
    /* a single 0x00 byte: known CCITT-FALSE value */
    CHECK(rslap_crc_ccitt((const uint8_t *)"\x00", 1) == 0xE1F0);

    /* golden sectors: CRC over the first 254 bytes must equal the stored
     * big-endian trailer */
    CHECK(rslap_crc_ccitt(GOLDEN_V7, GOLDEN_SECTOR_SIZE - 2) == GOLDEN_V7_CRC);
    CHECK(rslap_crc_ccitt(GOLDEN_V7_ROM, GOLDEN_SECTOR_SIZE - 2) == GOLDEN_V7_ROM_CRC);
    CHECK(rslap_crc_ccitt(GOLDEN_V1, GOLDEN_SECTOR_SIZE - 2) == GOLDEN_V1_CRC);
    CHECK(rslap_crc_ccitt(GOLDEN_DIR, GOLDEN_SECTOR_SIZE - 2) == GOLDEN_DIR_CRC);
    CHECK(rslap_crc_ccitt(GOLDEN_ROMDIR, GOLDEN_SECTOR_SIZE - 2) == GOLDEN_ROMDIR_CRC);

    /* crc_ok accepts all golden sectors and rejects any single-bit change */
    CHECK(rslap_crc_ok(GOLDEN_V7, GOLDEN_SECTOR_SIZE));
    CHECK(rslap_crc_ok(GOLDEN_V7_ROM, GOLDEN_SECTOR_SIZE));
    CHECK(rslap_crc_ok(GOLDEN_DIR, GOLDEN_SECTOR_SIZE));
    {
        uint8_t buf[GOLDEN_SECTOR_SIZE];
        memcpy(buf, GOLDEN_V7, sizeof(buf));
        buf[0x30] ^= 0x01; /* flip one bit of the first button record */
        CHECK(!rslap_crc_ok(buf, sizeof(buf)));
        buf[0x30] ^= 0x01;
        buf[GOLDEN_SECTOR_SIZE - 1] ^= 0x80; /* flip a CRC bit itself */
        CHECK(!rslap_crc_ok(buf, sizeof(buf)));
    }

    /* with_crc recomputes the trailer: zeroing it and recomputing must
     * reproduce the golden bytes exactly */
    {
        uint8_t buf[GOLDEN_SECTOR_SIZE];
        memcpy(buf, GOLDEN_V7, sizeof(buf));
        buf[GOLDEN_SECTOR_SIZE - 2] = 0;
        buf[GOLDEN_SECTOR_SIZE - 1] = 0;
        rslap_with_crc(buf, sizeof(buf));
        CHECK(memcmp(buf, GOLDEN_V7, sizeof(buf)) == 0);
        CHECK(rslap_crc_ok(buf, sizeof(buf)));
    }

    /* degenerate inputs must be rejected, not crash */
    CHECK(!rslap_crc_ok((const uint8_t *)"\x00\x00", 0));
    CHECK(!rslap_crc_ok((const uint8_t *)"\x12", 1));

    if (fails) {
        fprintf(stderr, "test_crc: %d check(s) failed\n", fails);
        return 1;
    }
    puts("test_crc: OK");
    return 0;
}
